//! Tests for loudness matching, the crossfade join, and the RNG.
//!
//! Fixtures live in `testdata/megatts3_post/`, regenerated by
//! `tools/gen_megatts3_post_fixtures.py` from pyloudnorm 0.1.1 and the
//! reference `combine_audio_segments`.

use std::path::{Path, PathBuf};

use super::postprocess::{
    combine_segments, integrated_loudness, match_loudness, CROSSFADE_SECONDS,
};
use super::rng::{Randomness, ReplayRng, SeededRng};
use super::tests::{f32s, max_diff};

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/megatts3_post")
}

fn cases() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(dir().join("cases.json")).unwrap()).unwrap()
}

#[test]
fn integrated_loudness_matches_pyloudnorm() {
    let c = cases();
    let mut checked = 0;
    for (name, want) in c["loudness"].as_object().unwrap() {
        let sig = f32s(&dir(), &format!("sig_{name}.npy"));
        match want {
            serde_json::Value::String(s) => {
                assert_eq!(s, "too_short");
                assert!(integrated_loudness(&sig, 24_000).is_err(), "{name}");
            }
            serde_json::Value::Null => {
                // Silence and sub-gate noise: every block is below -70 LUFS.
                assert_eq!(
                    integrated_loudness(&sig, 24_000).unwrap(),
                    f64::NEG_INFINITY,
                    "{name}"
                );
            }
            v => {
                let got = integrated_loudness(&sig, 24_000).unwrap();
                let want = v.as_f64().unwrap();
                println!("{name}: {got:.9} vs {want:.9} ({:e})", (got - want).abs());
                assert!((got - want).abs() < 1e-9, "{name}: {got} vs {want}");
                checked += 1;
            }
        }
    }
    assert!(checked >= 6, "only {checked} signals compared");
}

#[test]
fn loudness_rejects_bad_audio() {
    assert!(
        integrated_loudness(&vec![0.1; 9000], 24_000).is_err(),
        "shorter than 400 ms"
    );
    let mut bad = vec![0.1f32; 24_000];
    bad[5] = f32::NAN;
    assert!(integrated_loudness(&bad, 24_000).is_err());
    // A signal exactly one block long is accepted.
    assert!(integrated_loudness(&vec![0.1; 9600], 24_000)
        .unwrap()
        .is_finite());
}

#[test]
fn loudness_matching_and_peak_guard_match_the_reference() {
    let c = cases();
    let base = f32s(&dir(), "match_base.npy");
    let input = integrated_loudness(&base, 24_000).unwrap();
    for (i, m) in c["match"].as_array().unwrap().iter().enumerate() {
        let want = f32s(&dir(), &format!("match_{i}.npy"));
        let target = m["target"].as_f64().unwrap();
        assert!((input - m["input"].as_f64().unwrap()).abs() < 1e-6);
        let got = match_loudness(&base, input, target);
        let diff = max_diff(&got, &want);
        println!("match target {target}: diff {diff:e}, peak {:?}", m["peak"]);
        assert!(diff < 2e-6, "target {target}: {diff}");
    }
    // The loud targets must have exercised the 0.95 peak guard.
    assert!(c["match"]
        .as_array()
        .unwrap()
        .iter()
        .any(|m| (m["peak"].as_f64().unwrap() - 0.95).abs() < 1e-6));
}

#[test]
fn silent_loudness_leaves_audio_untouched() {
    let x = vec![0.25f32, -0.5, 0.0];
    assert_eq!(match_loudness(&x, f64::NEG_INFINITY, -18.0), x);
    assert_eq!(match_loudness(&x, -18.0, f64::NAN), x);
}

#[test]
fn crossfade_matches_combine_audio_segments() {
    let c = cases();
    for (k, combo) in c["combine"].as_array().unwrap().iter().enumerate() {
        let rate = combo["rate"].as_u64().unwrap() as u32;
        let segs: Vec<Vec<f32>> = (0..combo["sizes"].as_array().unwrap().len())
            .map(|i| f32s(&dir(), &format!("comb{k}_seg{i}.npy")))
            .collect();
        let got = combine_segments(&segs, rate).unwrap();
        let want = f32s(&dir(), &format!("comb{k}_out.npy"));
        assert_eq!(
            got.len(),
            combo["out_len"].as_u64().unwrap() as usize,
            "combo {k} length"
        );
        let diff = max_diff(&got, &want);
        println!("combine {k} (rate {rate}): {diff:e}");
        assert!(diff < 2e-6, "combo {k}: {diff}");
    }
}

#[test]
fn crossfade_edge_cases() {
    assert!(combine_segments(&[], 24_000).unwrap().is_empty());
    let one = vec![vec![0.5f32; 10]];
    assert_eq!(combine_segments(&one, 24_000).unwrap(), one[0]);
    // A segment shorter than the 0.16 s fade cannot be joined.
    let w = (24_000.0 * CROSSFADE_SECONDS) as usize;
    assert!(combine_segments(&[vec![0.0; w + 10], vec![0.0; w - 1]], 24_000).is_err());
    assert!(combine_segments(&[vec![0.0; w - 1], vec![0.0; w + 10]], 24_000).is_err());
    // Joined length is the sum minus one fade per join.
    let joined = combine_segments(
        &[vec![0.1; w + 100], vec![0.1; w + 50], vec![0.1; w + 7]],
        24_000,
    )
    .unwrap();
    assert_eq!(joined.len(), (w + 100) + (w + 50) + (w + 7) - 2 * w);
}

#[test]
fn seeded_rng_is_deterministic_and_well_formed() {
    let draw = |seed| {
        let mut r = SeededRng::new(seed);
        let (mut n, mut u) = (vec![0.0f32; 20_000], vec![0.0f32; 20_000]);
        r.normal(&mut n);
        r.uniform(&mut u);
        (n, u)
    };
    let (n1, u1) = draw(7);
    let (n2, u2) = draw(7);
    assert_eq!((n1.clone(), u1.clone()), (n2, u2), "same seed, same stream");
    assert_ne!(draw(8).0, n1, "different seed");
    let mean = n1.iter().map(|&v| f64::from(v)).sum::<f64>() / n1.len() as f64;
    let var = n1
        .iter()
        .map(|&v| (f64::from(v) - mean).powi(2))
        .sum::<f64>()
        / n1.len() as f64;
    assert!(
        mean.abs() < 0.03 && (var - 1.0).abs() < 0.05,
        "normal moments {mean} {var}"
    );
    assert!(n1.iter().all(|v| v.is_finite()));
    assert!(u1.iter().all(|&v| (0.0..1.0).contains(&v)));
    let umean = u1.iter().map(|&v| f64::from(v)).sum::<f64>() / u1.len() as f64;
    assert!((umean - 0.5).abs() < 0.01, "uniform mean {umean}");
}

#[test]
fn replay_rng_follows_the_recorded_order() {
    let mut r = ReplayRng::new(vec![vec![1.0, 2.0], vec![3.0]], vec![vec![0.5]]);
    let (mut a, mut b, mut c) = ([0.0f32; 2], [0.0f32; 1], [0.0f32; 1]);
    r.normal(&mut a);
    r.uniform(&mut c);
    assert!(!r.is_exhausted());
    r.normal(&mut b);
    assert_eq!((a, b, c), ([1.0, 2.0], [3.0], [0.5]));
    assert!(r.is_exhausted());
}

#[test]
#[should_panic(expected = "size mismatch")]
fn replay_rng_rejects_a_wrong_sized_draw() {
    let mut r = ReplayRng::new(vec![vec![1.0, 2.0]], vec![]);
    r.normal(&mut [0.0f32; 3]);
}

#[test]
#[should_panic(expected = "no uniform draws left")]
fn replay_rng_rejects_running_out() {
    ReplayRng::new(vec![], vec![]).uniform(&mut [0.0f32; 1]);
}
